verses.tafsir:
[ <span class="arabic uthmani">قُلْ مَا كُنْتُ بِدْعًا مِنَ الرُّسُلِ</span> ] ئه‌ی محمد - <span class="saw">صلی الله علیه وسلم</span> -  پێیان بڵێ: من بیدعه‌ نیم له‌ پێغه‌مبه‌ران، واته‌: یه‌كه‌م پێغه‌مبه‌ر نیم كه‌ خوای گه‌وره‌ منی ناردبێت و پێش من هیچ پێغه‌مبه‌ری تر نه‌هاتبێت، به‌ڵكو هه‌زاره‌ها پێغه‌مبه‌ر له‌ پێش مندا هاتوون.
{پێغه‌مبه‌رى خوایش - <span class="saw">صلی الله علیه وسلم</span> - غه‌یبى نه‌زانیوه‌}
 [ <span class="arabic uthmani">وَمَا أَدْرِي مَا يُفْعَلُ بِي وَلَا بِكُمْ</span> ] وه‌ من نازانم له‌ داهاتوودا خوای گه‌وره‌ چی به‌سه‌ر من و ئێوه‌ش دێنێت، واته‌: ئایا له‌ مه‌ككه‌ ئه‌مێنم یان ده‌رده‌كرێم، ئه‌كوژرێم یان نا، یان خوای گه‌وره‌ له‌ دونیادا سزای ئێوه‌ ئه‌دات یان هه‌ڵیئه‌گرێت بۆ قیامه‌ت، ئه‌مه‌ له‌ دونیادا به‌ڵام له‌ قیامه‌تدا پێغه‌مبه‌ر - <span class="saw">صلی الله علیه وسلم</span> -  زانیوێتی كه‌ یه‌كه‌م كه‌سه‌ كه‌ ئه‌چێته‌ به‌هه‌شته‌وه‌و خوای گه‌وره‌ رێزی لێده‌نێت، وه‌ كافرانیش ده‌خرێنه‌ دۆزه‌خ و سه‌ختترین سزا ده‌درێن [ <span class="arabic uthmani">إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ</span> ] من ته‌نها شوێنی ئه‌و وه‌حیه‌ ئه‌كه‌وم كه‌ له‌لایه‌ن خوای گه‌وره‌وه‌ بۆم دێت و ناتوانم له‌ خۆمه‌وه‌ هیچ شتێك بڵێم [ <span class="arabic uthmani">وَمَا أَنَا إِلَّا نَذِيرٌ مُبِينٌ (٩)</span> ] وه‌ من هیچ شتێك نیم ته‌نها ترسێنه‌رێكی ئاشكرا نه‌بێت له‌لایه‌ن خوای گه‌وره‌وه‌ ئه‌تانترسێنم به‌ ئایه‌ته‌كانی خوای گه‌وره‌.

{له‌ كاتى جه‌نگدا له‌ گه‌ردنى كافران بده‌ن}
 [ <span class="arabic uthmani">فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ</span> ] وه‌ ئه‌گه‌ر گه‌یشتن به‌ كافران له‌ مه‌یدانی جه‌نگدا ئه‌وه‌ بده‌ن له‌ گه‌ردنیان [ <span class="arabic uthmani">حَتَّى إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَ</span> ] تا كوشتارێكی زۆریان لێ ئه‌كه‌ن وه‌ لاوازیان ئه‌كه‌ن ئه‌و كاته‌ ئه‌وانه‌ی كه‌ به‌ دیل گرتان بیانبه‌ستنه‌وه‌ بۆ ئه‌وه‌ی ڕانه‌كه‌ن [ <span class="arabic uthmani">فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً</span> ] دوای كۆتایی هاتنی جه‌نگ و كوشتار ئه‌توانن به‌بێ به‌رامبه‌ر دیله‌كان ئازاد بكه‌ن یاخود به‌به‌رامبه‌ر ئازادیان بكه‌ن [ <span class="arabic uthmani">حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا</span> ] تا جه‌نگ كۆتایی دێت له‌گه‌ڵ كافراندا، یاخود تا چه‌كه‌كانیان فڕێ ئه‌ده‌ن و تێكئه‌شكێن، یاخود تا شه‌ریك دانان بۆ خوا نامێنێت [ <span class="arabic uthmani">ذَلِكَ وَلَوْ يَشَاءُ اللَّهُ لَانْتَصَرَ مِنْهُمْ</span> ] ئه‌گه‌ر خوای گه‌وره‌ ویستی لێ بێت خۆی به‌سه‌ر كافراندا سه‌ر ئه‌كه‌وێ وه‌ توانای سه‌ركه‌وتنی هه‌یه‌ به‌سه‌ریانداو ئه‌توانێ له‌ناویان ببات و له‌لایه‌ن خۆیه‌وه‌ سزایان بۆ بنێرێت به‌بێ ئه‌وه‌ی كه‌ باوه‌ڕداران شه‌ڕ بكه‌ن [ <span class="arabic uthmani">وَلَكِنْ لِيَبْلُوَ بَعْضَكُمْ بِبَعْضٍ</span> ] به‌ڵام خوای گه‌وره‌ كه‌ ئه‌م جه‌نگ و كوشتاره‌ له‌سه‌ر ئێوه‌ پێویست ئه‌كات بۆ ئه‌وه‌ی كه‌ هه‌ندێكتان به‌ هه‌ندێكتان تاقیبكاته‌وه‌ تا ده‌ربكه‌وێ كێ ئارامگره‌ وه‌ كێ ڕاستگۆیه‌
{تایبه‌تمه‌ندێكانى شه‌هید لاى خواى گه‌وره‌}
 [ <span class="arabic uthmani">وَالَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أَعْمَالَهُمْ (٤)</span> ] وه‌ ئه‌وانه‌یشی كه‌ له‌ پێناوی خوای گه‌وره‌دا كوژراون خوای گه‌وره‌ كرده‌وه‌كانیان نافه‌وتێنێ و به‌ڵكو گه‌شه‌ی پێده‌كات و زیادی ده‌كات و ئه‌جرو پاداشتی ته‌واویان ئه‌داته‌وه‌، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌فه‌رمێت: (شه‌هید لای خوای گه‌وره‌ شه‌ش تایبه‌تمه‌ندێتی بۆ هه‌یه‌: له‌گه‌ڵ یه‌كه‌م دڵۆپه‌ خوێن كه‌ لێی ده‌ڕژێت خوای گه‌وره‌ له‌ هه‌موو تاوانه‌كانی خۆش ده‌بێت، ته‌نها قه‌رزاری نه‌بێت، وه‌ شوێنی خۆی له‌ به‌هه‌شت ده‌بینێت، وه‌ تاجی رێزی له‌سه‌ر ده‌كرێت كه‌نه‌خش كراوه‌ به‌ دوڕڕو مرواری، هه‌ر مرواریه‌كی له‌ هه‌موو دونیاو ئه‌وه‌ی تێیدایه‌ چاكتره‌، وه‌ حه‌فتاو دوو حۆری پێ ده‌درێت، وه‌ له‌ سزای گۆڕ پارێزراو ده‌بێت، وه‌ شه‌فاعه‌ت بۆ حه‌فتا كه‌س له‌ خزمه‌كانی ده‌كات).

[ <span class="arabic uthmani">وَيَقُولُ الَّذِينَ آمَنُوا لَوْلَا نُزِّلَتْ سُورَةٌ</span> ] وه‌ باوه‌ڕداران ئه‌ڵێن: ئه‌وه‌ بۆچی خوای گه‌وره‌ سووره‌تێك دانابه‌زێنێت كه‌ فه‌رمان بكات به‌ جیهادو كوشتاری كافران [ <span class="arabic uthmani">فَإِذَا أُنْزِلَتْ سُورَةٌ مُحْكَمَةٌ وَذُكِرَ فِيهَا الْقِتَالُ</span> ] به‌ڵام كاتێك كه‌ سووره‌تێكی موحكه‌م دابه‌زێ كه‌ ماناكه‌ی ئاشكرا بێت، یان مه‌نسوخ نه‌بێ وه‌ باسی كوشتاری كافرانی تیابێ
{هه‌ندێك له‌ سیفاتى مونافیقان}
 [ <span class="arabic uthmani">رَأَيْتَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ يَنْظُرُونَ إِلَيْكَ نَظَرَ الْمَغْشِيِّ عَلَيْهِ مِنَ الْمَوْتِ</span> ] ئه‌و كه‌سانه‌ی كه‌ نه‌خۆشی دوودڵی و گومان له‌ دڵیاندایه‌ كه‌ مونافیقانن ئه‌بینی كه‌ ته‌ماشات ئه‌كه‌ن وه‌كو ته‌ماشا كردنی كه‌سێك كه‌ له‌ سه‌ره‌مه‌رگدا بێت كاتێك كه‌ چاوی تێ ئه‌ڕوانێت له‌به‌ر ترسنۆكیان له‌ رووبه‌ڕووبوونه‌وه‌ی دوژمن [ <span class="arabic uthmani">فَأَوْلَى لَهُمْ (٢٠)</span> ] هه‌ڕه‌شه‌و تیاچوون بۆ ئه‌و كه‌سانه‌ی كه‌ حاڵیان وایه‌، یاخود باشتر وابوو كه‌ گوێڕایه‌ڵ بوونایا.

{موژده‌ دانى به‌هه‌شت به‌ هه‌زارو چوارسه‌د صه‌حابه‌ }
 [ <span class="arabic uthmani">لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ</span> ] ئه‌ى پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  به‌ دڵنیایی خوای گه‌وره‌ ڕازی بوو له‌و باوه‌ڕدارانه‌ی كه‌ له‌ ژێر ئه‌و داره‌دا به‌یعه‌ت به‌ تۆ ئه‌ده‌ن له‌ حوده‌یبیه‌ كه‌ ژماره‌یان هه‌زارو چوار سه‌د یان هه‌زارو پێنج سه‌د كه‌س بوو، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  فه‌رمووى: (ئه‌وانه‌ى له‌ ژێر ئه‌و داره‌ به‌یعه‌تیاندا هیچ كه‌سێكیان ناچنه‌ دۆزه‌خه‌وه‌) به‌یعه‌ته‌كه‌ بۆ تۆڵه‌ سه‌ندن بوو بۆ خوێنى ئیمامى عوسمان كه‌ پڕوپاگه‌نده‌ بڵاو بوه‌وه‌ كه‌ كوژراوه‌، كه‌ پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ناردى بۆ مه‌ككه‌ بۆ ئه‌وه‌ى گفتوگۆ له‌گه‌ڵ قوڕه‌یش بكات تا رێگایان بده‌ن بچنه‌ مه‌ككه‌وه‌و عومره‌ بكه‌ن، به‌ڵام ئه‌وان رێگایان نه‌داو دواتر رێككه‌وتننامه‌ى (حوده‌یبیه‌) كرا، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌ستێكى خسته‌ ناو ده‌سته‌كه‌ى ترى و فه‌رمووى: (خوایه‌ عوسمان بۆ پێویستى خواو پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  رۆیشتووه‌) ده‌ستى پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  بۆ عوسمان باشتر بوو له‌ ده‌ستى ئه‌وان بۆ خۆیان، (سه‌عیدى كوڕى موسه‌ییب) ده‌فه‌رمێت: باوكم له‌و كه‌سانه‌ بوو كه‌ له‌ ژێر ئه‌و داره‌ به‌یعه‌تى به‌ پێغه‌مبه‌ری خوادا - <span class="saw">صلی الله علیه وسلم</span> - ، باوكم فه‌رمووى: ساڵى دواتر رۆیشتینه‌وه‌ بۆ حوده‌یبیه‌ له‌ بیرمان كرد و نه‌مانزانى كام داره‌ بوو، سه‌عید فه‌رمووى: هاوه‌ڵانى پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  له‌ یادیان چوو نه‌یانزانى كام داره‌یه‌ ئێستا ئێوه‌ ده‌یزانن!؟ (خواى گه‌وره‌ له‌ بیرى بردنه‌وه‌ بۆ ئه‌وه‌ى كه‌ خه‌ڵكى نه‌چنه‌ سه‌رى و نه‌یپه‌رستن، كه‌ ئه‌و داره‌ دروست نه‌بێت بپه‌رسترێت و بچیته‌ سه‌رى دارو به‌ردى تر چۆن دروسته‌!!؟) {شایه‌تى دانى خواى گه‌وره‌ بۆ صه‌حابه‌}
 [ <span class="arabic uthmani">فَعَلِمَ مَا فِي قُلُوبِهِمْ</span> ] خوای گه‌وره‌ زانی چی له‌ دڵیاندا هه‌یه‌ له‌ ڕاستگۆیی و به‌ ئه‌مه‌كى و گوێڕایه‌ڵى و دامه‌زراوی [ <span class="arabic uthmani">فَأَنْزَلَ السَّكِينَةَ عَلَيْهِمْ</span> ] خوای گه‌وره‌ش هێمنی و ئارامی دابه‌زانده‌ سه‌ر دڵیان [ <span class="arabic uthmani">وَأَثَابَهُمْ فَتْحًا قَرِيبًا (١٨)</span> ] وه‌ دواتریش پاداشتی دانه‌وه‌ به‌ فه‌تحێكی نزیك كه‌ فه‌تحی خه‌یبه‌رو فه‌تحی مه‌ككه‌و شوێنه‌كانى تر بوو.

[ <span class="arabic uthmani">هُمُ الَّذِينَ كَفَرُوا وَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ</span> ] كافران ئه‌وان بوون كه‌ كوفریان كرد وه‌ ڕێگری ئێوه‌یان كرد له‌ (مسجد الحرام) له‌ كه‌عبه‌ی پیرۆز كه‌ بڕۆن عومره‌ بكه‌ن كه‌ ئێوه‌ شایانتر بوون له‌ وان [ <span class="arabic uthmani">وَالْهَدْيَ مَعْكُوفًا أَنْ يَبْلُغَ مَحِلَّهُ</span> ] وه‌ ڕێگریشیان كرد له‌و ئاژه‌ڵ و حوشترانه‌ی كه‌ بردبووتان بۆ سه‌ربڕین نه‌یانهێشت بگاته‌ شوێنی خۆی هه‌ر له‌ حوده‌یبیه‌ له‌وێ سه‌ریان بڕی
{دواخستنى فه‌تحى مه‌ككه‌ له‌به‌ر نۆ موسڵمان!}
 [ <span class="arabic uthmani">وَلَوْلَا رِجَالٌ مُؤْمِنُونَ وَنِسَاءٌ مُؤْمِنَاتٌ لَمْ تَعْلَمُوهُمْ أَنْ تَطَئُوهُمْ فَتُصِيبَكُمْ مِنْهُمْ مَعَرَّةٌ بِغَيْرِ عِلْمٍ</span> ] خوای گه‌وره‌ ڕێگای نه‌دا كه‌ ئێوه‌ كوشتاری كافران بكه‌ن له‌به‌ر ئه‌وه‌ی كۆمه‌ڵێك پیاوی باوه‌ڕدارو ئافره‌تی باوه‌ڕدار كه‌ ئێوه‌ نایانناسن له‌ناو مه‌ككه‌دا ماونه‌ته‌وه‌و باوه‌ڕدارن ئیمانی خۆیان شاردۆته‌وه‌ كه‌ وتراوه‌: نۆ كه‌س بوونه‌ حه‌وت پیاو و دوو ئافره‌ت، ئه‌و ساڵه‌ له‌به‌ر خاتری ئه‌وانه‌ خوای گه‌وره‌ فه‌تحی مه‌ككه‌ی دواخست نه‌وه‌كو ئێوه‌ بیانكوژن و نه‌یانناسن وابزانن كافرن ئه‌و كاته‌ تووشی تاوان ئه‌بن و كه‌فاره‌ت ئه‌كه‌وێته‌ سه‌رتان بۆیه‌ دوای خست، (موسڵمان لاى خواى گه‌وره‌ ئه‌وه‌نده‌ به‌ڕێزه‌ ساڵێك فه‌تحى مه‌ككه‌و حه‌ج و عومره‌ى دواخست له‌به‌ر ئه‌و چه‌ند موسڵمانه‌ كه‌ له‌ مه‌ككه‌ مابوونه‌وه‌ نه‌وه‌كو به‌ هه‌ڵه‌ بكوژرێن، به‌ڵام هه‌ندێك له‌ موسڵمانان زۆر به‌ ئاسانى خوێنى موسڵمانان ده‌رێژن و به‌لایانه‌وه‌ ئاساییه‌!! خوایه‌ په‌نامان بده‌یت و بمانپارێزیت) [ <span class="arabic uthmani">لِيُدْخِلَ اللَّهُ فِي رَحْمَتِهِ مَنْ يَشَاءُ</span> ] تا خوای گه‌وره‌ هه‌ر كه‌سێك بخاته‌ ناو ڕه‌حمه‌تی خۆیه‌وه‌و بگه‌ڕێته‌وه‌ بۆ ئیسلام كه‌ ویستى لێ بێت وه‌ك ئه‌و باوه‌ڕدارانه‌ی كه‌ له‌ مه‌ككه‌دا ماونه‌ته‌وه‌ [ <span class="arabic uthmani">لَوْ تَزَيَّلُوا لَعَذَّبْنَا الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابًا أَلِيمًا (٢٥)</span> ] ئه‌گه‌ر كافران و موسڵمانان لێك جیا ببنه‌وه‌ به‌ ته‌واوه‌تی و باوه‌ڕداران له‌ناو كافراندا نه‌مێنن ئه‌وه‌ ئێمه‌ سزایه‌كی زۆر به‌ئێش و ئازاری كافران ئه‌ده‌ین به‌ كوشتن.

{هه‌ندێك له‌ سیفاتى صه‌حابه‌كان}
 [ <span class="arabic uthmani">مُحَمَّدٌ رَسُولُ اللَّهِ</span> ] محمد - <span class="saw">صلی الله علیه وسلم</span> -  پێغه‌مبه‌ری خوایه‌ - <span class="saw">صلی الله علیه وسلم</span> -  [ <span class="arabic uthmani">وَالَّذِينَ مَعَهُ</span> ] وه‌ ئه‌و صه‌حابه‌ به‌ڕێزانه‌ى له‌گه‌ڵی بوون [ <span class="arabic uthmani">أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ</span> ] سه‌خت و توندن له‌گه‌ڵ كافراندا، وه‌ له‌ نێوان خۆیاندا زۆر به‌ڕه‌حم و سۆزو به‌زه‌یی و میهره‌بانن، كه‌ ده‌بێت مرۆڤى باوه‌ڕدار وا بێت [ <span class="arabic uthmani">تَرَاهُمْ رُكَّعًا سُجَّدًا</span> ] ئه‌یانبینی هه‌میشه‌ له‌ ڕكوع و سجوددان و نوێژ ئه‌كه‌ن بۆ خوای گه‌وره‌ [ <span class="arabic uthmani">يَبْتَغُونَ فَضْلًا مِنَ اللَّهِ وَرِضْوَانًا</span> ] مه‌به‌ست و نیه‌تیان ده‌ستخستنی فه‌زڵ و چاكه‌و ڕه‌زامه‌ندی خوای گه‌وره‌یه‌، (خواى گه‌وره‌ نیه‌تى پاكى صه‌حابه‌ ده‌رده‌خات و شایه‌تى نیازپاكیان بۆ ده‌دات، چۆن ده‌بێت له‌ پاش ئه‌م شایه‌تییه‌ى خواى گه‌وره‌ بۆیان خه‌ڵكى قسه‌یان پێ بڵێت و جوێنیان پێ بدات و تۆمه‌تباریان بكات؟!!) [ <span class="arabic uthmani">سِيمَاهُمْ فِي وُجُوهِهِمْ مِنْ أَثَرِ السُّجُودِ</span> ] نیشانه‌ى خشوع و خۆبه‌كه‌مزانین و شێوه‌و ره‌وشت جوانی و دره‌وشاوه‌ی له‌ ڕوویاندا دیاره‌ به‌هۆی زۆرى شوێنه‌واری سوجده‌ بردن و نوێژ كردنیان، (هه‌ركه‌سێك به‌شه‌و شه‌ونوێژ بكات به‌ رۆژ رووى جوان ده‌بێت و پێوه‌ى دیار ده‌بێت) [ <span class="arabic uthmani">ذَلِكَ مَثَلُهُمْ فِي التَّوْرَاةِ وَمَثَلُهُمْ فِي الْإِنْجِيلِ</span> ] له‌ ته‌ورات و ئینجیلیشدا وه‌سفی ئه‌م صه‌حابه‌ به‌ڕێزانه‌ به‌و شێوازه‌ كراوه‌ [ <span class="arabic uthmani">كَزَرْعٍ أَخْرَجَ شَطْأَهُ فَآزَرَهُ</span> ] نموونه‌ی ئه‌م صه‌حابه‌ به‌ڕێزانه‌ وه‌كو نموونه‌ی ڕووه‌كێك وایه‌ كه‌ سه‌ره‌تا لاوازه‌و دواتر به‌هێز ئه‌بێت و پێ ئه‌گات و گه‌وره‌ ئه‌بێت [ <span class="arabic uthmani">فَاسْتَغْلَظَ</span> ] وه‌ له‌ پاش ئه‌وه‌ی كه‌ ته‌نك و ناسكه‌ دواتر ئه‌ستوورو به‌هێزو درێژ ئه‌بێت [ <span class="arabic uthmani">فَاسْتَوَى عَلَى سُوقِهِ</span> ] ئه‌و كاته‌ له‌سه‌ر پێی خۆی له‌سه‌ر داره‌كه‌ی خۆی ڕائه‌وه‌ستێ [ <span class="arabic uthmani">يُعْجِبُ الزُّرَّاعَ لِيَغِيظَ بِهِمُ الْكُفَّارَ</span> ] جووتیاره‌كه‌ زۆر پێی سه‌رسام ئه‌بێت، كه‌ ئه‌مه‌یش نموونه‌ی صه‌حابه‌ به‌ڕێزه‌كانه‌ كه‌ سه‌ره‌تا لاوازو بێ هێزو كه‌م بوون دواتر خوای گه‌وره‌ به‌هێزی كردن و زۆری كردن تا ببێته‌ خه‌فه‌ت خواردن بۆ كافران و كافران كه‌ ده‌یانبینن خه‌فه‌تیان پێ بخۆن و رقیان لێیان بێت، (ئیمامى مالیك و كۆمه‌ڵێك له‌ زانایان له‌م ئایه‌ته‌وه‌ ئه‌و حوكمه‌یان وه‌رگرتووه‌ كه‌ هه‌ر كه‌سێك رقى له‌ صه‌حابه‌ بێت ئه‌وه‌ كافر ده‌بێت).
{خواى گه‌وره‌ موژده‌ى به‌هه‌شت به‌ صه‌حابه‌ ده‌دات}
 [ <span class="arabic uthmani">وَعَدَ اللَّهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنْهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا (٢٩)</span> ] خوای گه‌وره‌ به‌ڵێنی داوه‌ به‌و باوه‌ڕدارانه‌ى كه‌ كرده‌وه‌ی چاكیان كردووه‌ به‌ لێخۆشبوون و ئه‌جرو پاداشتێكی زۆر گه‌وره‌ كه‌ به‌هه‌شته‌، (كرده‌وه‌ى چاك ئه‌وه‌یه‌ بۆ خوا بێت و بۆ ریا نه‌بێت، وه‌ له‌سه‌ر سوننه‌ت بێت و بیدعه‌ نه‌بێت، وه‌ ئه‌م ئایه‌ته‌ موژده‌دانه‌ به‌ صه‌حابه‌ به‌ به‌هه‌شت) والله أعلم.

{گاڵته‌ به‌ یه‌كترى مه‌كه‌ن}
 [ <span class="arabic uthmani">يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ عَسَى أَنْ يَكُونُوا خَيْرًا مِنْهُمْ</span> ] ئه‌ی باوه‌ڕداران با كه‌سانێك گاڵته‌ به‌ كه‌سانێكی تر نه‌كه‌ن له‌وانه‌یه‌ گاڵته‌پێكراوه‌كه‌ لای خوای گه‌وره‌ له‌وه‌ باشتر بێ كه‌ گاڵته‌ی پێ ئه‌كات [ <span class="arabic uthmani">وَلَا نِسَاءٌ مِنْ نِسَاءٍ عَسَى أَنْ يَكُنَّ خَيْرًا مِنْهُنَّ</span> ] وه‌ با ئافره‌تانیش گاڵته‌ نه‌كه‌ن به‌ ئافره‌تانێكی تر له‌وانه‌یه‌ ئافره‌ته‌ گاڵته‌پێكراوه‌كان لای خوای گه‌وره‌ باشتر بن له‌وانه‌ی كه‌ گاڵته‌یان پێ ئه‌كه‌ن
{تانه‌وته‌شه‌ر له‌ یه‌كترى مه‌ده‌ن}
 [ <span class="arabic uthmani">وَلَا تَلْمِزُوا أَنْفُسَكُمْ</span> ] وه‌ تانه‌و ته‌شه‌ر له‌ خۆتان مه‌ده‌ن، واته‌: تانه‌و ته‌شه‌ر له‌ یه‌كتری مه‌ده‌ن، (چونكه‌ ئه‌گه‌ر تانه‌و ته‌شه‌رت له‌ خه‌ڵكیدا وه‌ك ئه‌وه‌ وایه‌ تانه‌و ته‌شه‌رت له‌ خۆت دابێت و ته‌نها خۆت زه‌ره‌رمه‌ند و تاوانبار ده‌بیت)
{ناو و ناتۆره‌ى ناشیرین له‌ یه‌كتر مه‌نێن}
 [ <span class="arabic uthmani">وَلَا تَنَابَزُوا بِالْأَلْقَابِ</span> ] وه‌ ناو و ناتۆره‌ی ناشیرین له‌ یه‌كتری مه‌نێن، (ابو جبيرة بن الضحاك) ده‌فه‌رمێت: ئه‌م ئایه‌ته‌ ده‌رباره‌ى ئێمه‌ى (به‌نى سه‌لیمه‌) دابه‌زى، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  هاته‌ مه‌دینه‌ هیچ پیاوێك له‌ ئێمه‌ نه‌بوو ئیلا دوو سێ ناوى هه‌بوو، كه‌ به‌و ناوانه‌ بانگ بكرایه‌ پێى ناخۆش بوو، خواى گه‌وره‌ ئه‌م ئایه‌ته‌ى دابه‌زاند [ <span class="arabic uthmani">بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ</span> ] له‌ دوای ئیمان هێنان خراپترین ناو ئه‌وه‌یه‌ كه‌ ناو و ناتۆره‌ی خراپ له‌ یه‌كتری بنێن وه‌ ئه‌وه‌ فیسق و له‌ ڕێ ده‌رچوونه‌ [ <span class="arabic uthmani">وَمَنْ لَمْ يَتُبْ فَأُولَئِكَ هُمُ الظَّالِمُونَ (١١)</span> ] وه‌ هه‌ر كه‌سێكیش ته‌وبه‌ نه‌كات ئه‌وا ئه‌و كه‌سانه‌ سته‌مكارن.

{گومانى خراپ به‌ یه‌كتر مه‌به‌ن}
 [ <span class="arabic uthmani">يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ</span> ] ئه‌ی باوه‌ڕداران خۆتان دووربخه‌نه‌وه‌ له‌ زۆرێك له‌ گومان به‌تایبه‌تی گومان بردنی خراپ به‌ كه‌سانی چاك له‌به‌ر ئه‌وه‌ی هه‌ندێك له‌ گومان تاوانه‌، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌فه‌رمێت: (ئاگادارتان ده‌كه‌مه‌وه‌ له‌ گومان بردنى خراپ چونكه‌ درۆترین قسه‌یه‌)، وه‌ ئیمامى عومه‌ر ده‌فه‌رمێت: (گومانى باش نه‌بێت به‌ قسه‌ى برا باوه‌ڕداره‌كه‌تى مه‌به‌، له‌ كاتێكدا تۆ ده‌توانێت گومانى باشى پێببه‌یت و به‌ جوانى بۆى لێكبده‌یته‌وه‌و ماناى بكه‌یت)
{جاسوسی له‌سه‌ر یه‌كتری مه‌كه‌ن}
[ <span class="arabic uthmani">وَلَا تَجَسَّسُوا</span> ] وه‌ جاسوسی له‌سه‌ر یه‌كتری مه‌كه‌ن، (ته‌جه‌سوس) زیاتر بۆ خراپه‌ به‌كاردێت، (ته‌حه‌سوس) زیاتر بۆ چاكه‌ به‌كار دێت، وه‌كو پێغه‌مبه‌ر یه‌عقوب - <span class="saw">صلی الله علیه وسلم</span> -  به‌ كوڕه‌كانى فه‌رموو: بڕۆن (ته‌حه‌سوس) بكه‌ن له‌ یوسف و براكه‌ى، پیاوێكیان هێنا بۆ لاى (ابن مسعود) وتیان: ئه‌مه‌ فڵانه‌ كه‌سه‌ مه‌ى به‌ ریشیدا ده‌چۆڕێته‌وه‌، فه‌رمووى: قه‌ده‌غه‌ كراوین له‌ جاسوسى و سیخوڕى، به‌ڵام به‌ ئاشكرا شتێك ببینین ئه‌وا سزاى ده‌ده‌ین، (دخین)ى نوسه‌رى (عوقبه‌) ده‌ڵێت: به‌ (عوقبه‌)م وت: دراوسێیه‌كمان هه‌یه‌ مه‌ى ده‌خۆنه‌وه‌ منیش پۆلیسیان لێ ئاگادار ده‌كه‌مه‌وه‌ بیانبه‌ن، (عوقبه‌) وتى: وا مه‌كه‌ به‌ڵام ئامۆژگاریان بكه‌و هه‌ڕه‌شه‌یان لێبیكه‌، وایشى كرد هه‌ر وازیان نه‌هێنا، وتى ده‌چم پۆلیس ئاگادار ده‌كه‌مه‌وه‌، (عوقبه‌) وتى: هاوار بۆ خۆت نه‌كه‌یت، من گوێم له‌ پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  بووه‌ قه‌ده‌غه‌ى كردووه‌ دواى تاوانى خه‌ڵكى بكه‌ویت
{غه‌یبه‌تی یه‌كتری مه‌كه‌ن}
[ <span class="arabic uthmani">وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا</span> ] وه‌ غه‌یبه‌تی یه‌كتری مه‌كه‌ن، باسی برایه‌كت بكه‌ی به‌ شتێك كه‌ تیایدا بێت و پێی ناخۆش بێت ئه‌وه‌ غه‌یبه‌ته‌، وه‌ ئه‌گه‌ر تیایدا نه‌بێت ئه‌وه‌ بوهتانه‌و گه‌وره‌تره‌، (عائیشه‌) ته‌نها به‌ (صه‌فیه‌)ى وت: باڵاكورته‌، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  فه‌رمووى: (قسه‌یه‌كت كرد ئه‌گه‌ر بیكه‌یته‌ ناو ئاوى ده‌ریاوه‌ بۆگه‌نى ده‌كات) [ <span class="arabic uthmani">أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا</span> ] ئایا یه‌كێك له‌ ئێوه‌ پێی خۆشه‌ گۆشتی براكه‌ی بخوات به‌ مردوویه‌تی؟ ئه‌و كه‌سه‌یش كه‌ لێره‌ نیه‌ وه‌ك ئه‌وه‌ وایه‌ مردوو بێت و ناتوانێ به‌رگری له‌ خۆی بكات [ <span class="arabic uthmani">فَكَرِهْتُمُوهُ</span> ] ئێوه‌ پێتان ناخۆشه‌و لاتان بێزێندراوه‌ [ <span class="arabic uthmani">وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ تَوَّابٌ رَحِيمٌ (١٢)</span> ] وه‌ ئێوه‌ ته‌قوای خوای گه‌وره‌ بكه‌ن به‌ڕاستی خوای گه‌وره‌ زۆر ته‌وبه‌ی ئه‌و كه‌سانه‌ قبووڵ ئه‌كات كه‌ ته‌وبه‌ ئه‌كه‌ن، وه‌ زۆر به‌ره‌حم و به‌ به‌زه‌ییه‌.

[ <span class="arabic uthmani">يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى</span> ] ئه‌ی خه‌ڵكی ئێمه‌ ئێوه‌مان دروست كردووه‌ له‌ نێرو مێیه‌ك كه‌ ئاده‌م و حه‌وا بووه‌ [ <span class="arabic uthmani">وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا</span> ] وه‌ ئێوه‌مان كردووه‌ به‌ چه‌ند گه‌ل و هۆزێكه‌وه‌ تا یه‌كتری بناسن
{به‌ڕێزترینتان لای خوای گه‌وره‌ به‌ته‌قواترینتانه‌}
[ <span class="arabic uthmani">إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ</span> ] به‌ڕێزترینتان لای خوای گه‌وره‌ ئه‌و كه‌سه‌یه‌ كه‌ له‌ هه‌موو كه‌س به‌ته‌قواتر بێت ئه‌وه‌ لای خوای گه‌وره‌ له‌ هه‌موو كه‌س به‌ڕێزتره‌ [ <span class="arabic uthmani">إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ (١٣)</span> ] به‌ دڵنیایى خوای گه‌وره‌ زۆر زانایه‌ وه‌ زانیاریه‌كی زۆر وردی هه‌یه‌.

[ <span class="arabic uthmani">وَأَصْحَابُ الْأَيْكَةِ</span> ] وه‌ هاوه‌ڵانی داره‌كه‌ كه‌ له‌ كه‌ناری ده‌ریا بوون تا (مه‌دیه‌ن)، كه‌ خوای گه‌وره‌ شوعه‌یب پێغه‌مبه‌ری - <span class="saw">صلی الله علیه وسلم</span> -  بۆ ناردن ئه‌وانیش شوعه‌یبیان به‌درۆ زانی.
{(توببەع) كێ‌ بووە؟}
 [ <span class="arabic uthmani">وَقَوْمُ تُبَّعٍ</span> ] وه‌ قه‌ومی (توببه‌ع)یش كه‌ له‌ یه‌مه‌ن بوونه‌، به‌ پاشاى یه‌مه‌ن ده‌وترا: (توببه‌ع)، هه‌روه‌كو به‌ پاشاى فارس وتراوه‌: (كیسرا)، وه‌ به‌ پاشاى رۆم وتراوه‌: (قه‌یصه‌ر)، وه‌ به‌ پاشاى كافرى میصر وتراوه‌: (فیرعه‌ون)، وه‌ به‌ پاشاى حه‌به‌شه‌ وتراوه‌: (نه‌جاشى)، (توببه‌ع) ناوى (اسعد بن أبو كریب) بووه‌، پاشایه‌كی یه‌مه‌ن بووه‌و سێ سه‌دو بیست و شه‌ش ساڵ پاشایان بووه‌، له‌ناویاندا كه‌س له‌م ته‌مه‌نى گه‌وره‌تر نه‌بووه‌، سه‌ربازو سوپاى یه‌كجار زۆری هه‌بووه‌، ده‌سه‌ڵاتى گه‌یشتۆته‌ (سه‌مه‌رقه‌ندو حیره‌و دیمه‌شق)، هاتۆته‌ مه‌دینه‌ ویستویه‌تى كوشتارى خه‌ڵكه‌كه‌ى بكات دوو زاناى جوله‌كه‌ وتویانه‌ ئه‌مه‌ شارى كۆچكردنى كۆتا پێغه‌مبه‌ره‌، پاشان موسڵمان بووه‌و چۆته‌ سه‌ر دینى موساو - <span class="saw">صلی الله علیه وسلم</span> -  رۆیشتووه‌ بۆ مه‌ككه‌و له‌گه‌ڵ خۆى بردوونى، ویستۆتى كه‌عبه‌ بڕوخێنێت، دوو زاناكه‌ نه‌یانهێشتوه‌و وتویانه‌ ئیبراهیم پێغه‌مبه‌ر - <span class="saw">صلی الله علیه وسلم</span> -  دروستى كردووه‌و له‌سه‌ر ده‌ستى كۆتا پێغه‌مبه‌ر پله‌وپایه‌ى به‌رزى ده‌بێت، ئه‌ویش به‌گه‌وره‌ى زانیوه‌و ته‌وافى به‌ده‌وردا كردووه‌و په‌رده‌ى له‌ ئاوریشم بۆ كردووه‌، پاشان گه‌ڕاوه‌ته‌وه‌ بۆ یه‌مه‌ن و خه‌ڵكى هه‌موویان موسڵمان بوونه‌و چونه‌ته‌ سه‌ر دینى موسا پێغه‌مبه‌ر - <span class="saw">صلی الله علیه وسلم</span> -  ، پێش ناردنى پێغه‌مبه‌رى خوا - <span class="saw">صلی الله علیه وسلم</span> -  به‌ حه‌وت سه‌د ساڵ كۆچى دوایی كردووه‌، به‌ شیعر وتویه‌تى: ئه‌گه‌ر بگه‌م به‌ كۆتا پێغه‌مبه‌ر شوێنى ده‌كه‌وم و به‌رگرى لێده‌كه‌م، وه‌ پێغه‌مبه‌رى خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌فه‌رمێت: (جوێن به‌ توببه‌ع مه‌ده‌ن چونكه‌ موسڵمان بووه‌) به‌ڵام له‌ پاش مردنى (توببه‌ع) قه‌ومه‌كه‌ى گه‌ڕاونه‌ته‌وه‌ بۆ سه‌ر بت په‌رستى و خواى گه‌وره‌ له‌ناوى بردوون [ <span class="arabic uthmani">كُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَعِيدِ (١٤)</span> ] هه‌ر هه‌موو ئه‌مانه‌ پێغه‌مبه‌رانی خۆیان به‌درۆ زانیوه‌ بۆیه‌ هه‌ڕه‌شه‌و سزای خوای گه‌وره‌ جێبه‌جێ بوو به‌سه‌ریاندا، بۆیه‌ با كافرانى قوڕه‌یشیش ئاگادار بن ئه‌گه‌ر ئیمان نه‌هێنن خواى گه‌وره‌ تواناى هه‌یه‌ ئه‌مانیش وه‌كو ئه‌و نه‌ته‌وانه‌ى تر له‌ناو بدات.
